  EXPECT_THROW(owner_queue.front()(), std::runtime_error);
  owner_queue.clear();
  EXPECT_TRUE(gate->closed(failed));
  EXPECT_FALSE(gate->closed(sibling));
  ASSERT_TRUE(gate->close_batch(keys, post, [] {}));
  ASSERT_EQ(owner_queue.size(), 1u);
  EXPECT_TRUE(gate->closed(failed));
