TEST(GpuAliasIngressGateTest, BatchClosesAtomicallyAndRetriesFailedMaintenance) {
  auto gate = std::make_shared<rocjitsu::GpuAliasIngressGate>();
  const rocjitsu::GpuAliasIngressGate::Key owner{1, 101, 0x1000, 7, 11};
  const rocjitsu::GpuAliasIngressGate::Key requester{1, 202, 0x1000, 7, 12};
  const rocjitsu::GpuAliasIngressGate::Key unrelated{1, 303, 0x3000, 8, 13};
  const std::array keys{requester, owner};
  const std::array owner_key{owner};
  const std::array requester_key{requester};
  const std::array unrelated_key{unrelated};
  auto held_owner = gate->try_acquire(owner_key);
  auto held_requester = gate->try_acquire(requester_key);
  ASSERT_TRUE(held_owner);
  ASSERT_TRUE(held_requester);
  std::vector<std::function<void()>> owner_queue;
  const auto post = [&](std::function<void()> continuation) {
    owner_queue.push_back(std::move(continuation));
  };
  uint32_t drained = 0;
  ASSERT_TRUE(gate->close_batch(keys, post, [&] { ++drained; }));
  EXPECT_TRUE(gate->closed(owner));
  EXPECT_TRUE(gate->closed(requester));
  EXPECT_FALSE(gate->closed(unrelated));
  EXPECT_FALSE(gate->try_acquire(keys));
  EXPECT_TRUE(gate->try_acquire(unrelated_key));
  held_owner->reset();
  EXPECT_TRUE(owner_queue.empty());
  held_requester->reset();
  ASSERT_EQ(owner_queue.size(), 1u);
  EXPECT_FALSE(gate->reopen_batch(keys));
  owner_queue.back()();
  owner_queue.clear();
  EXPECT_EQ(drained, 1u);
  ASSERT_TRUE(gate->reopen_batch(keys));
  EXPECT_EQ(gate->tracked_generation_count(), 0u);

  ASSERT_TRUE(
      gate->close_batch(keys, post, [] { throw std::runtime_error("maintenance failed"); }));
  ASSERT_EQ(owner_queue.size(), 1u);
  EXPECT_THROW(owner_queue.back()(), std::runtime_error);
  owner_queue.clear();
  EXPECT_FALSE(gate->reopen_batch(keys));
  EXPECT_FALSE(gate->close_batch(keys, post, [&] { ++drained; }));
  ASSERT_TRUE(gate->retry_closed_batch(keys, post, [&] { ++drained; }));
  EXPECT_FALSE(gate->retry_closed_batch(keys, post, [&] { ++drained; }));
  ASSERT_EQ(owner_queue.size(), 1u);
  owner_queue.back()();
  owner_queue.clear();
  EXPECT_EQ(drained, 2u);
  ASSERT_TRUE(gate->reopen_batch(keys));

  const auto failed_post = [](std::function<void()>) { throw std::runtime_error("post failed"); };
  EXPECT_FALSE(gate->close_batch(keys, failed_post, [&] { ++drained; }));
  EXPECT_TRUE(gate->closed(owner));
  EXPECT_TRUE(gate->closed(requester));
  ASSERT_TRUE(gate->retry_closed_batch(keys, post, [&] { ++drained; }));
  ASSERT_EQ(owner_queue.size(), 1u);
  owner_queue.back()();
  owner_queue.clear();
  EXPECT_EQ(drained, 3u);
  EXPECT_TRUE(gate->reopen_batch(keys));
  EXPECT_EQ(gate->tracked_generation_count(), 0u);

  ASSERT_TRUE(gate->close(owner, post, [] { throw std::runtime_error("single failed"); }));
  ASSERT_EQ(owner_queue.size(), 1u);
  EXPECT_THROW(owner_queue.back()(), std::runtime_error);
  owner_queue.clear();
  ASSERT_TRUE(gate->close_batch(keys, post, [&] { ++drained; }));
  ASSERT_EQ(owner_queue.size(), 1u);
  owner_queue.back()();
  owner_queue.clear();
  EXPECT_EQ(drained, 4u);
  EXPECT_TRUE(gate->reopen_batch(keys));

  ASSERT_TRUE(gate->close(owner, post, [] {}));
  EXPECT_FALSE(gate->close_batch(keys, post, [] {}));
  ASSERT_EQ(owner_queue.size(), 1u);
  owner_queue.back()();
  owner_queue.clear();
  ASSERT_TRUE(gate->reopen(owner));
  std::weak_ptr<rocjitsu::GpuAliasIngressGate> weak_gate = gate;
  gate.reset();
  EXPECT_TRUE(weak_gate.expired());
}

TEST(GpuAliasIngressGateTest, BatchDrainAuthorityAdmitsItsKeysOnlyDuringOwnerContinuation) {
  using Gate = rocjitsu::GpuAliasIngressGate;
  auto gate = std::make_shared<Gate>();
  const Gate::Key owner{1, 101, 0x1000, 7, 11};
  const Gate::Key requester{1, 202, 0x1000, 7, 12};
  const Gate::Key unrelated{1, 303, 0x3000, 8, 13};
  const std::array keys{owner, requester};
  const std::array owner_key{owner};
  const std::array requester_key{requester};
  const std::array unrelated_key{unrelated};
  const std::array mixed_keys{owner, unrelated};
  std::vector<std::function<void()>> owner_queue;
  const auto post = [&](std::function<void()> continuation) {
    owner_queue.push_back(std::move(continuation));
  };
  std::optional<Gate::DrainAuthority> retained;
  bool owner_admitted = false;
  ASSERT_TRUE(gate->close_batch_with_drain_authority(keys, post, [&](const auto &authority) {
    retained = authority;
    EXPECT_FALSE(gate->try_acquire(owner_key));
    EXPECT_FALSE(gate->try_acquire(requester_key));
    EXPECT_TRUE(gate->try_acquire(unrelated_key));
    auto permit = gate->try_acquire_for_drained_owner(keys, authority);
    ASSERT_TRUE(permit);
    owner_admitted = true;
    permit->reset();
    auto mixed_permit = gate->try_acquire_for_drained_owner(mixed_keys, authority);
    ASSERT_TRUE(mixed_permit);
    mixed_permit->reset();
    EXPECT_FALSE(gate->final_writeback_done(authority).value_or(true));
    EXPECT_TRUE(gate->mark_final_writeback_done(authority));
    EXPECT_TRUE(gate->final_writeback_done(authority).value_or(false));
  }));
  ASSERT_EQ(owner_queue.size(), 1u);
  EXPECT_TRUE(gate->closed(owner));
  EXPECT_TRUE(gate->closed(requester));
  EXPECT_FALSE(gate->try_acquire(keys));
  owner_queue.front()();
  EXPECT_TRUE(owner_admitted);
  ASSERT_TRUE(retained);
  EXPECT_FALSE(gate->try_acquire_for_drained_owner(keys, *retained));
  EXPECT_FALSE(gate->mark_final_writeback_done(*retained));
  EXPECT_FALSE(gate->final_writeback_done(*retained));
  EXPECT_TRUE(gate->reopen_batch(keys));
  EXPECT_EQ(gate->tracked_generation_count(), 0u);
}

TEST(GpuAliasIngressGateTest, EffectFreezeRejectsBusySelectionAtomically) {
  using Gate = rocjitsu::GpuAliasIngressGate;
  auto gate = std::make_shared<Gate>();
  const Gate::Key owner{1, 101, 0x1000, 7, 11};
  const Gate::Key importer{1, 202, 0x2000, 7, 12};
  const Gate::Key unrelated{2, 303, 0x3000, 8, 13};
  const std::array selected{owner, importer, owner};
  const std::array owner_key{owner};
  const std::array importer_key{importer};
  const std::array unrelated_key{unrelated};

  auto held = gate->try_acquire(importer_key);
  ASSERT_TRUE(held);
  EXPECT_FALSE(gate->try_freeze_for_effect(selected));
  EXPECT_FALSE(gate->closed(owner));
  EXPECT_FALSE(gate->closed(importer));
  EXPECT_TRUE(gate->try_acquire(owner_key));
  EXPECT_EQ(gate->tracked_generation_count(), 1u);
  held->reset();

  auto window = gate->try_freeze_for_effect(selected);
  ASSERT_TRUE(window);
  EXPECT_EQ(gate->tracked_generation_count(), 2u);
  EXPECT_TRUE(gate->closed(owner));
  EXPECT_TRUE(gate->closed(importer));
  EXPECT_FALSE(gate->close_claimed());
  EXPECT_FALSE(gate->close_claimed_by_process(1));
  EXPECT_FALSE(gate->close_claimed_by_process(2));
  EXPECT_FALSE(gate->try_acquire(owner_key));
  EXPECT_FALSE(gate->try_acquire(importer_key));
  EXPECT_TRUE(gate->try_acquire(unrelated_key));
  EXPECT_FALSE(gate->try_freeze_for_effect(unrelated_key));
  window.reset();
  EXPECT_FALSE(gate->closed(owner));
  EXPECT_FALSE(gate->closed(importer));
  EXPECT_FALSE(gate->close_claimed());
  EXPECT_EQ(gate->tracked_generation_count(), 0u);
  EXPECT_TRUE(gate->try_acquire(owner_key));
}

TEST(GpuAliasIngressGateTest, EffectBypassRequiresLiveExactWindow) {
  using Gate = rocjitsu::GpuAliasIngressGate;
  auto gate = std::make_shared<Gate>();
  auto other_gate = std::make_shared<Gate>();
  const Gate::Key owner{1, 101, 0x1000, 7, 11};
  const Gate::Key importer{1, 202, 0x2000, 7, 12};
  const Gate::Key unrelated{2, 303, 0x3000, 8, 13};
  const std::array selected{owner, importer};
  const std::array owner_key{owner};
  const std::array importer_key{importer};
  const std::array unrelated_key{unrelated};
  const std::array mixed{owner, unrelated};

  EXPECT_FALSE(gate->try_freeze_for_effect({}));
  auto window = gate->try_freeze_for_effect(selected);
  ASSERT_TRUE(window);
  Gate::EffectWindow moved = std::move(*window);
  EXPECT_FALSE(*window);
  EXPECT_FALSE(gate->try_acquire_for_effect(owner_key, *window));
  EXPECT_FALSE(other_gate->try_acquire_for_effect(owner_key, moved));
  EXPECT_FALSE(gate->try_acquire_for_effect({}, moved));
  EXPECT_FALSE(gate->try_acquire_for_effect(unrelated_key, moved));
  EXPECT_FALSE(gate->try_acquire_for_effect(mixed, moved));

  auto owner_bypass = gate->try_acquire_for_effect(owner_key, moved);
  auto importer_bypass = gate->try_acquire_for_effect(importer_key, moved);
  ASSERT_TRUE(owner_bypass);
  ASSERT_TRUE(importer_bypass);
  EXPECT_FALSE(gate->try_acquire(selected));
  importer_bypass->reset();
  owner_bypass->reset();
  moved.reset();
  EXPECT_FALSE(gate->try_acquire_for_effect(owner_key, moved));
  EXPECT_FALSE(gate->close_claimed());
  EXPECT_EQ(gate->tracked_generation_count(), 0u);
}

TEST(GpuAliasIngressGateTest, EffectReleaseWaitsForBypassAndExcludesRetirement) {
  using Gate = rocjitsu::GpuAliasIngressGate;
  auto gate = std::make_shared<Gate>();
  const Gate::Key owner{1, 101, 0x1000, 7, 11};
  const Gate::Key importer{1, 202, 0x2000, 7, 12};
  const Gate::Key unrelated{2, 303, 0x3000, 8, 13};
  const std::array selected{owner, importer};
  const std::array owner_key{owner};
  const std::array unrelated_key{unrelated};
  std::function<void()> pending;
  const auto post = [&](std::function<void()> continuation) { pending = std::move(continuation); };

  ASSERT_TRUE(gate->close(owner, post, [] {}));
  EXPECT_FALSE(gate->try_freeze_for_effect(selected));
  ASSERT_TRUE(pending);
  pending();
  pending = {};
  ASSERT_TRUE(gate->reopen(owner));

  auto window = gate->try_freeze_for_effect(selected);
  ASSERT_TRUE(window);
  auto bypass = gate->try_acquire_for_effect(owner_key, *window);
  ASSERT_TRUE(bypass);
  EXPECT_FALSE(gate->close(unrelated, post, [] {}));
  EXPECT_FALSE(gate->close_batch(selected, post, [] {}));
  EXPECT_FALSE(gate->closed(unrelated));
  window->reset();
  EXPECT_FALSE(gate->try_acquire_for_effect(owner_key, *window));
  EXPECT_TRUE(gate->closed(owner));
  EXPECT_TRUE(gate->closed(importer));
  EXPECT_FALSE(gate->close_claimed());
  EXPECT_FALSE(gate->close(unrelated, post, [] {}));
  EXPECT_FALSE(gate->try_freeze_for_effect(unrelated_key));
  EXPECT_TRUE(gate->try_acquire(unrelated_key));

  bypass->reset();
  EXPECT_FALSE(gate->closed(owner));
  EXPECT_FALSE(gate->closed(importer));
  EXPECT_FALSE(gate->close_claimed());
  EXPECT_EQ(gate->tracked_generation_count(), 0u);
  ASSERT_TRUE(gate->close(unrelated, post, [] {}));
  ASSERT_TRUE(pending);
  pending();
  EXPECT_TRUE(gate->reopen(unrelated));
}

class ChildProcessGuard {
public:
  explicit ChildProcessGuard(pid_t pid) : pid_(pid) {}
  ~ChildProcessGuard() {
    if (pid_ <= 0)
      return;
    kill(pid_, SIGKILL);
    int status = 0;
    while (waitpid(pid_, &status, 0) == -1 && errno == EINTR) {
    }
  }

  ChildProcessGuard(const ChildProcessGuard &) = delete;
  ChildProcessGuard &operator=(const ChildProcessGuard &) = delete;

  void release() { pid_ = -1; }

private:
  pid_t pid_;
};

int daemon_debug_enable(rocjitsu::SimulatedKfd &daemon, uint32_t debugger,
                        kfd_ioctl_dbg_trap_args &args) {
  const std::string proc_path = std::format("/proc/{}", args.pid);
  const int proc_fd = ::open(proc_path.c_str(), O_RDONLY | O_DIRECTORY | O_CLOEXEC);
  if (proc_fd < 0)
    return -errno;
  int mem_fd = ::openat(proc_fd, "mem", O_RDWR | O_CLOEXEC);
  if (mem_fd < 0) {
    const int open_errno = errno;
    ::close(proc_fd);
    return -open_errno;
  }
  const int result = daemon.ioctl(debugger, AMDKFD_IOC_DBG_TRAP, &args, &mem_fd, proc_fd);
  if (mem_fd >= 0)
    ::close(mem_fd);
  ::close(proc_fd);
  return result;
}

uint32_t query_gb_addr_config(const std::string &config_path, uint32_t gpu_id) {
  util::StringDiagnostic loaded_diagnostic;
  auto loaded_result = rocjitsu::config::load_config(config_path.c_str(), rocjitsu::kEmbeddedSchema,
                                                     loaded_diagnostic.emitter());
  if (loaded_result.failed()) {
    ADD_FAILURE() << loaded_diagnostic.message();
    return 0;
  }
  auto loaded = std::move(loaded_result).value();
  auto root = loaded.take_root();
  auto *soc = dynamic_cast<rocjitsu::SoC *>(root.get());
  if (!soc)
    return 0;
  auto num_xcds = soc->num_xcds();

  // These tests drive the engine directly and inspect single-partition state, so
  // pin one worker instead of taking the config's default of one partition per
  // XCD.
  loaded.engine_config.num_threads = 1;
  loaded.engine_config.max_ticks = 0;
  loaded.engine_config.await_primaries = true;
  simdojo::SimulationEngine engine(loaded.engine_config);

  auto soc_root = std::unique_ptr<rocjitsu::SoC>(static_cast<rocjitsu::SoC *>(root.release()));
  auto vm = std::make_unique<rocjitsu::VirtualMachine>(std::move(soc_root));
  auto *driver = vm->driver();

  engine.topology().set_root(std::move(vm));
  loaded.wire_links(engine.topology());
  soc->wire_backing(engine.topology());
  engine.create();
  engine.register_as_primary();

  driver->setup_topology(loaded.device, num_xcds);
  int fd = driver->open();
  if (fd < 0)
    return 0;

  kfd_ioctl_get_tile_config_args args{};
  args.gpu_id = gpu_id;
  int rc = driver->ioctl(AMDKFD_IOC_GET_TILE_CONFIG, &args);
  driver->close();
  return rc == 0 ? args.gb_addr_config : 0;
}

std::unique_ptr<rocjitsu::SoC> load_standalone_soc(const std::string &config_path) {
  util::StringDiagnostic loaded_diagnostic;
  auto loaded_result = rocjitsu::config::load_config(config_path.c_str(), rocjitsu::kEmbeddedSchema,
                                                     loaded_diagnostic.emitter());
  if (loaded_result.failed()) {
    ADD_FAILURE() << loaded_diagnostic.message();
    return nullptr;
  }
  auto loaded = std::move(loaded_result).value();
  auto root = loaded.take_root();
  auto *soc = dynamic_cast<rocjitsu::SoC *>(root.get());
  if (!soc)
    return nullptr;
  root.release();
  return std::unique_ptr<rocjitsu::SoC>(soc);
}

class KfdIoctlTest : public ::testing::Test {
protected:
  void SetUp() override { SetUpWithConfig(CONFIG_PATH); }

  // Split out so a fixture can bring up a different part. Uses ASSERT_*, so it
  // has to stay void-returning and be called directly from SetUp().
  void SetUpWithConfig(const std::string &config_path) {
    setenv("RJ_CONFIG", config_path.c_str(), 1);
    ASSERT_TRUE(rocjitsu::test::load_valid_config(config_path.c_str(), loaded_));
    auto root = loaded_.take_root();
    auto *soc = dynamic_cast<rocjitsu::SoC *>(root.get());
    ASSERT_NE(soc, nullptr);
    soc_ = soc;
    auto num_xcds = soc->num_xcds();

    // These tests drive the engine directly and inspect single-partition state,
    // so pin one worker instead of taking the config's default of one partition
    // per XCD.
    loaded_.engine_config.num_threads = 1;
    loaded_.engine_config.max_ticks = 0;
    loaded_.engine_config.await_primaries = true;
    engine_ = std::make_unique<simdojo::SimulationEngine>(loaded_.engine_config);

    auto soc_root = std::unique_ptr<rocjitsu::SoC>(static_cast<rocjitsu::SoC *>(root.release()));
    auto vm = std::make_unique<rocjitsu::VirtualMachine>(std::move(soc_root));
    driver_ = vm->driver();

    engine_->topology().set_root(std::move(vm));
    loaded_.wire_links(engine_->topology());
    soc->wire_backing(engine_->topology());
    engine_->create();
    engine_->register_as_primary();

    driver_->setup_topology(loaded_.device, num_xcds);
    kfd_fd_ = driver_->open();
    ASSERT_GE(kfd_fd_, 0);
  }

  void TearDown() override {
    if (driver_)
      driver_->close();
    for (int fd : debug_fds_)
      ::close(fd);
    debug_fds_.clear();
  }

  // Returns a real eventfd standing in for a debugger's notification target.
  // kfd_dbg_trap_enable() takes a reference to dbg_fd via fget(), so the driver
  // rejects an unusable descriptor; enable-success tests therefore need a live
  // fd. Tracked here so TearDown closes it.
  int make_debug_fd() {
    int fd = eventfd(0, EFD_CLOEXEC | EFD_NONBLOCK);
    EXPECT_GE(fd, 0);
    debug_fds_.push_back(fd);
    return fd;
  }

  /// @brief Read one VM-relative dword through the address-space service.
  /// @details Debugger tests operate on process virtual addresses. Returning
  /// zero on an unavailable or faulted access keeps the helper usable by the
  /// CWSR callback API, whose legacy signature cannot carry a typed outcome;
  /// the surrounding test assertions still reject the missing data.
  uint32_t vm_read32(uint64_t address, uint32_t vmid) const {
    const std::optional<rocjitsu::amdgpu::GpuVmAccess> access = soc_->gpu_vm().snapshot_vmid(vmid);
    if (!access)
      return 0;
    const rocjitsu::amdgpu::AtomicLoadResult result =
        access->atomic_load(address, sizeof(uint32_t));
    return result.outcome == rocjitsu::amdgpu::VmAccessOutcome::Complete
               ? static_cast<uint32_t>(result.value)
               : 0;
  }

  /// @brief Write one VM-relative dword through the address-space service.
  rocjitsu::amdgpu::VmAccessOutcome vm_write32(uint64_t address, uint32_t value,
                                               uint32_t vmid) const {
    const std::optional<rocjitsu::amdgpu::GpuVmAccess> access = soc_->gpu_vm().snapshot_vmid(vmid);
    return access ? access->atomic_store(address, sizeof(value), value)
                  : rocjitsu::amdgpu::VmAccessOutcome::Unavailable;
  }

  /// @brief Read one VM-relative qword through the address-space service.
  /// @details Debugger tests operate on process virtual addresses. Returning
  /// zero on an unavailable or faulted access keeps the helper usable by the
  /// CWSR callback API, whose legacy signature cannot carry a typed outcome;
  /// the surrounding test assertions still reject the missing data.
  uint64_t vm_read64(uint64_t address, uint32_t vmid) const {
    const std::optional<rocjitsu::amdgpu::GpuVmAccess> access = soc_->gpu_vm().snapshot_vmid(vmid);
    if (!access)
      return 0;
    const rocjitsu::amdgpu::AtomicLoadResult result =
        access->atomic_load(address, sizeof(uint64_t));
    return result.outcome == rocjitsu::amdgpu::VmAccessOutcome::Complete
               ? static_cast<uint64_t>(result.value)
               : 0;
  }

  /// @brief Write one VM-relative qword through the address-space service.
  rocjitsu::amdgpu::VmAccessOutcome vm_write64(uint64_t address, uint64_t value,
                                               uint32_t vmid) const {
    const std::optional<rocjitsu::amdgpu::GpuVmAccess> access = soc_->gpu_vm().snapshot_vmid(vmid);
    return access ? access->atomic_store(address, sizeof(value), value)
                  : rocjitsu::amdgpu::VmAccessOutcome::Unavailable;
  }

  void expect_combined_event_subscription_transition(uint64_t initial_mask, uint64_t updated_mask,
                                                     bool publish_from_retry = false) {
    constexpr uint64_t kMemoryViolation = KFD_EC_MASK(EC_QUEUE_WAVE_MEMORY_VIOLATION);
    constexpr uint64_t kWaveTrap = KFD_EC_MASK(EC_QUEUE_WAVE_TRAP);
    constexpr uint64_t kCombined = kMemoryViolation | kWaveTrap;
    ASSERT_NE(initial_mask & kCombined, 0u);
    ASSERT_NE(updated_mask & kCombined, 0u);

    alignas(rocjitsu::amdgpu::kAqlPacketBytes) std::array<uint8_t, 4096> ring{};
    uint64_t read_pointer = 0;
    uint64_t write_pointer = 0;
    kfd_ioctl_create_queue_args create{};
    create.gpu_id = kGpuId;
    create.queue_type = KFD_IOC_QUEUE_TYPE_COMPUTE_AQL;
    create.ring_base_address = reinterpret_cast<uint64_t>(ring.data());
    create.ring_size = static_cast<uint32_t>(ring.size());
    create.read_pointer_address = reinterpret_cast<uint64_t>(&read_pointer);
    create.write_pointer_address = reinterpret_cast<uint64_t>(&write_pointer);
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &create), 0);

    const int notifier = eventfd(0, EFD_CLOEXEC | EFD_NONBLOCK);
    ASSERT_GE(notifier, 0);
    debug_fds_.push_back(notifier);
    kfd_ioctl_dbg_trap_args enable{};
    enable.pid = static_cast<uint32_t>(getpid());
    enable.op = KFD_IOC_DBG_TRAP_ENABLE;
    enable.enable.dbg_fd = notifier;
    enable.enable.exception_mask = initial_mask;
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &enable), 0);

    kfd_queue_snapshot_entry snapshot_entry{};
    kfd_ioctl_dbg_trap_args snapshot{};
    snapshot.pid = static_cast<uint32_t>(getpid());
    snapshot.op = KFD_IOC_DBG_TRAP_GET_QUEUE_SNAPSHOT;
    snapshot.queue_snapshot.exception_mask = KFD_EC_MASK(EC_QUEUE_NEW);
    snapshot.queue_snapshot.snapshot_buf_ptr = reinterpret_cast<uint64_t>(&snapshot_entry);
    snapshot.queue_snapshot.num_queues = 1;
    snapshot.queue_snapshot.entry_size = sizeof(snapshot_entry);
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &snapshot), 0);

    kfd_ioctl_dbg_trap_args exceptions{};
    exceptions.pid = static_cast<uint32_t>(getpid());
    exceptions.op = KFD_IOC_DBG_TRAP_SET_EXCEPTIONS_ENABLED;
    int mask_update_result = -1;
    if (publish_from_retry) {
      driver_->set_debug_notifier_dup_error_for_testing(EMFILE);
      EXPECT_FALSE(driver_->notify_debug_event_for_testing(create.queue_id, kCombined,
                                                           /*retain_on_rejection=*/true));

      auto write_entered = std::make_shared<std::promise<void>>();
      auto write_entered_future = write_entered->get_future();
      auto release_write = std::make_shared<std::promise<void>>();
      auto release_write_future = release_write->get_future().share();
      driver_->set_debug_notification_write_hook_for_testing([write_entered, release_write_future] {
        write_entered->set_value();
        release_write_future.wait();
      });
      driver_->set_debug_notifier_dup_error_for_testing(std::nullopt);
      if (write_entered_future.wait_for(std::chrono::seconds(2)) != std::future_status::ready) {
        release_write->set_value();
        driver_->set_debug_notification_write_hook_for_testing({});
        FAIL() << "background notification retry did not reach the writer";
        return;
      }

      exceptions.set_exceptions_enabled.exception_mask = updated_mask;
      mask_update_result = driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &exceptions);
      release_write->set_value();
      pollfd ready{notifier, POLLIN, 0};
      EXPECT_EQ(::poll(&ready, 1, 2000), 1);
      driver_->set_debug_notification_write_hook_for_testing({});
    } else {
      driver_->set_debug_notification_result_hook_for_testing([&](bool delivered) {
        if (!delivered)
          return;
        exceptions.set_exceptions_enabled.exception_mask = updated_mask;
        mask_update_result = driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &exceptions);
      });
      EXPECT_TRUE(driver_->notify_debug_event_for_testing(create.queue_id, kCombined,
                                                          /*retain_on_rejection=*/true,
                                                          /*reserve_runtime_on_rejection=*/true));
      driver_->set_debug_notification_result_hook_for_testing({});
    }
    EXPECT_EQ(mask_update_result, 0);

    uint64_t notifications = 0;
    ASSERT_EQ(::read(notifier, &notifications, sizeof(notifications)),
              static_cast<ssize_t>(sizeof(notifications)));
    EXPECT_EQ(notifications, 1u);

    auto process = driver_->find_process(driver_->local_process_id());
    ASSERT_NE(process, nullptr);
    {
      std::lock_guard<std::mutex> lock(process->alloc_mutex_);
      auto queue = process->queue_snapshot_map_.find(create.queue_id);
      ASSERT_NE(queue, process->queue_snapshot_map_.end());
      EXPECT_EQ(queue->second.runtime_exception_pending_status & kCombined, 0u);
    }

    kfd_ioctl_dbg_trap_args query{};
    query.pid = static_cast<uint32_t>(getpid());
    query.op = KFD_IOC_DBG_TRAP_QUERY_DEBUG_EVENT;
    query.query_debug_event.exception_mask = kCombined;
    int query_result = -EAGAIN;
    for (int attempt = 0; attempt < 200 && query_result == -EAGAIN; ++attempt) {
      query.query_debug_event.exception_mask = kCombined;
      query_result = driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &query);
      if (query_result == -EAGAIN)
        static_cast<void>(::poll(nullptr, 0, 10));
    }
    ASSERT_EQ(query_result, 0);
    EXPECT_EQ(query.query_debug_event.queue_id, create.queue_id);
    EXPECT_EQ(query.query_debug_event.exception_mask, kCombined);
  }

  void expect_queue_wakeup_after_early_query(bool retry) {
    constexpr uint64_t kException = KFD_EC_MASK(EC_QUEUE_WAVE_TRAP);
    alignas(rocjitsu::amdgpu::kAqlPacketBytes) std::array<uint8_t, 4096> ring{};
    uint64_t read_pointer = 0;
    uint64_t write_pointer = 0;
    kfd_ioctl_create_queue_args create{};
    create.gpu_id = kGpuId;
    create.queue_type = KFD_IOC_QUEUE_TYPE_COMPUTE_AQL;
    create.ring_base_address = reinterpret_cast<uint64_t>(ring.data());
    create.ring_size = ring.size();
    create.read_pointer_address = reinterpret_cast<uint64_t>(&read_pointer);
    create.write_pointer_address = reinterpret_cast<uint64_t>(&write_pointer);
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &create), 0);

    const int notifier = make_debug_fd();
    kfd_ioctl_dbg_trap_args enable{};
    enable.pid = static_cast<uint32_t>(getpid());
    enable.op = KFD_IOC_DBG_TRAP_ENABLE;
    enable.enable.dbg_fd = notifier;
    enable.enable.exception_mask = kException;
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &enable), 0);
    if (retry) {
      driver_->set_debug_notifier_dup_error_for_testing(EMFILE);
      EXPECT_FALSE(driver_->notify_debug_event_for_testing(create.queue_id, kException, true));
    }
    auto early_query_done = std::make_shared<std::promise<void>>();
    auto early_query_done_future = early_query_done->get_future();
    auto early_query_result = std::make_shared<std::atomic<int>>(-1);
    driver_->set_debug_notification_result_hook_for_testing(
        [this, notifier, pid = enable.pid, early_query_done, early_query_result](bool delivered) {
          EXPECT_TRUE(delivered);
          uint64_t notification = 0;
          EXPECT_EQ(::read(notifier, &notification, sizeof(notification)),
                    static_cast<ssize_t>(sizeof(notification)));
          kfd_ioctl_dbg_trap_args query{};
          query.pid = pid;
          query.op = KFD_IOC_DBG_TRAP_QUERY_DEBUG_EVENT;
          query.query_debug_event.exception_mask = kException;
          early_query_result->store(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &query));
          early_query_done->set_value();
        });
    if (retry) {
      driver_->set_debug_notifier_dup_error_for_testing(std::nullopt);
      EXPECT_EQ(early_query_done_future.wait_for(std::chrono::seconds(2)),
                std::future_status::ready);
    } else {
      EXPECT_TRUE(driver_->notify_debug_event_for_testing(create.queue_id, kException, false));
    }
    driver_->set_debug_notification_result_hook_for_testing({});
    ASSERT_TRUE(early_query_result->load() == 0 || early_query_result->load() == -EAGAIN);
    if (early_query_result->load() == -EAGAIN) {
      // A consumer goes back to poll after draining the first wake. It must
      // not need timer-driven QUERY calls to discover the committed event.
      pollfd ready{notifier, POLLIN, 0};
      ASSERT_EQ(::poll(&ready, 1, 2000), 1);
      uint64_t notification = 0;
      ASSERT_EQ(::read(notifier, &notification, sizeof(notification)),
                static_cast<ssize_t>(sizeof(notification)));
      kfd_ioctl_dbg_trap_args query{};
      query.pid = enable.pid;
      query.op = KFD_IOC_DBG_TRAP_QUERY_DEBUG_EVENT;
      query.query_debug_event.exception_mask = kException;
      ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &query), 0);
      EXPECT_EQ(query.query_debug_event.queue_id, create.queue_id);
      EXPECT_NE(query.query_debug_event.exception_mask & kException, 0u);
    }
  }

  void expect_process_notification_after_early_query(bool raise_before_commit,
                                                     bool clear_exception_info = false) {
    constexpr uint64_t kException = KFD_EC_MASK(EC_PROCESS_RUNTIME);
    const int notifier = make_debug_fd();
    kfd_ioctl_dbg_trap_args enable{};
    enable.pid = static_cast<uint32_t>(getpid());
    enable.op = KFD_IOC_DBG_TRAP_ENABLE;
    enable.enable.dbg_fd = notifier;
    enable.enable.exception_mask = kException;
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &enable), 0);
    auto consumed = std::make_shared<std::atomic<bool>>(false);
    driver_->set_debug_notification_result_hook_for_testing([this, notifier, pid = enable.pid,
                                                             consumed, raise_before_commit,
                                                             clear_exception_info](bool delivered) {
      if (consumed->exchange(true))
        return;
      EXPECT_TRUE(delivered);
      uint64_t notification = 0;
      EXPECT_EQ(::read(notifier, &notification, sizeof(notification)),
                static_cast<ssize_t>(sizeof(notification)));
      kfd_ioctl_dbg_trap_args query{};
      query.pid = pid;
      if (clear_exception_info) {
        query.op = KFD_IOC_DBG_TRAP_QUERY_EXCEPTION_INFO;
        query.query_exception_info.exception_code = EC_PROCESS_RUNTIME;
        query.query_exception_info.clear_exception = 1;
      } else {
        query.op = KFD_IOC_DBG_TRAP_QUERY_DEBUG_EVENT;
        query.query_debug_event.exception_mask = kException;
      }
      EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &query), 0);
      if (raise_before_commit)
        driver_->raise_process_debug_event_for_testing(pid, kException);
    });
    driver_->raise_process_debug_event_for_testing(enable.pid, kException);
    driver_->set_debug_notification_result_hook_for_testing({});
    EXPECT_TRUE(consumed->load());
    if (!raise_before_commit)
      driver_->raise_process_debug_event_for_testing(enable.pid, kException);
    pollfd ready{notifier, POLLIN, 0};
    ASSERT_EQ(::poll(&ready, 1, 2000), 1);
    uint64_t notification = 0;
    ASSERT_EQ(::read(notifier, &notification, sizeof(notification)),
              static_cast<ssize_t>(sizeof(notification)));
    kfd_ioctl_dbg_trap_args query{};
    query.pid = enable.pid;
    query.op = KFD_IOC_DBG_TRAP_QUERY_DEBUG_EVENT;
    query.query_debug_event.exception_mask = kException;
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DBG_TRAP, &query), 0);
    EXPECT_EQ(query.query_debug_event.exception_mask, kException);
  }

  rocjitsu::config::LoadedConfig loaded_;
  std::unique_ptr<simdojo::SimulationEngine> engine_;
  rocjitsu::SoC *soc_ = nullptr;
  rocjitsu::SimulatedKfd *driver_ = nullptr;
  int kfd_fd_ = -1;
  std::vector<int> debug_fds_;
};

TEST_F(KfdIoctlTest, ReportsImplementedKfdUapiVersion) {
  kfd_ioctl_get_version_args version{};
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_GET_VERSION, &version), 0);
  EXPECT_EQ(version.major_version, 1u);
  EXPECT_EQ(version.minor_version, 18u);
  EXPECT_EQ(KFD_IOCTL_MINOR_VERSION, 19)
      << "Shared KFD header changed; audit new fields and ioctls before updating the simulator's "
         "reported UAPI version";
}

TEST_F(KfdIoctlTest, RejectsUnsupportedMetadataRingQueueCreation) {
  alignas(4096) std::array<std::byte, 8192> ring{};
  alignas(64) std::array<uint64_t, 8> ptrs{};

  kfd_ioctl_create_queue_args args{};
  args.gpu_id = kGpuId;
  args.queue_type = KFD_IOC_QUEUE_TYPE_COMPUTE_AQL;
  args.ring_base_address = reinterpret_cast<uint64_t>(ring.data());
  args.ring_size = static_cast<uint32_t>(ring.size());
  args.read_pointer_address = reinterpret_cast<uint64_t>(&ptrs[0]);
  args.write_pointer_address = reinterpret_cast<uint64_t>(&ptrs[1]);
  args.queue_percentage = 100;
  args.metadata_ring_size = 4096;

  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &args), -EINVAL);
  args.metadata_ring_size = 0;
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &args), 0);
  kfd_ioctl_destroy_queue_args destroy{};
  destroy.queue_id = args.queue_id;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_DESTROY_QUEUE, &destroy), 0);
}

TEST_F(KfdIoctlTest, CloseReleasesProcessAfterCompletedOrAbortedInstructionExecution) {
  for (const bool abort : {false, true}) {
    SCOPED_TRACE(abort ? "aborted dispatch" : "completed quantum");
    if (abort) {
      ASSERT_GE(driver_->open(), 0);
    }

    constexpr uint64_t kKernelAddress = 0x600000000ULL;
    alignas(4096) std::array<uint8_t, 4096> code{};
    const std::array<uint32_t, 3> instructions = {0xBF800000u, 0xBF800000u,
                                                  0xBF810000u}; // s_nop; s_nop; s_endpgm
    std::memcpy(code.data(), instructions.data(), sizeof(instructions));
    const uint32_t pid = driver_->local_process_id();
    auto process = driver_->find_process(pid);
    ASSERT_NE(process, nullptr);
    const std::weak_ptr<rocjitsu::KfdProcess> lifetime = process;
    process->map_pages(kKernelAddress, code.data(), code.size());

    rocjitsu::amdgpu::ComputeUnitCore *cu = nullptr;
    soc_->for_each_cp([&](rocjitsu::amdgpu::CommandProcessor *cp) {
      if (cu == nullptr && !cp->compute_units().empty())
        cu = cp->compute_units().front();
    });
    ASSERT_NE(cu, nullptr);
    auto *wave = cu->dispatch_wf(/*wg_id=*/0, kKernelAddress, /*sgprs=*/16, /*vgprs=*/4);
    ASSERT_NE(wave, nullptr);
    wave->set_process_id(pid);
    wave->set_dispatch_id(7);
    if (abort) {
      cu->step();
      ASSERT_EQ(wave->pc, kKernelAddress + sizeof(uint32_t));
      ASSERT_FALSE(wave->is_halted());
      cu->abort_dispatch(7);
    } else {
      cu->set_functional_quantum(4);
      EXPECT_EQ(cu->run_quantum().iterations, 2u);
    }
    ASSERT_TRUE(wave->is_halted());
    process.reset();
    ASSERT_FALSE(lifetime.expired());

    ASSERT_EQ(driver_->close(), 0);
    EXPECT_TRUE(lifetime.expired())
        << "the idle CU retained the closed KFD process while its VM stayed alive";
  }
}

// Same driver surface, brought up on a part whose CWSR layout is not modelled.
// Deriving does not inherit KfdIoctlTest's cases: TEST_F registers against the
// fixture it names, so only the cases written against this one run here.
class KfdIoctlRdna3Test : public KfdIoctlTest {
protected:
  void SetUp() override { SetUpWithConfig(RDNA3_CONFIG_PATH); }
};

TEST_F(KfdIoctlRdna3Test, ConcurrentUnpublishableStopsAreRaceFree) {
  constexpr uint32_t kThreadCount = 8;
  std::atomic<uint32_t> ready = 0;
  std::atomic<bool> start = false;
  std::atomic<bool> unexpectedly_publishable = false;
  {
    std::vector<std::jthread> callers;
    callers.reserve(kThreadCount);
    for (uint32_t i = 0; i < kThreadCount; ++i) {
      callers.emplace_back([&] {
        ready.fetch_add(1, std::memory_order_release);
        while (!start.load(std::memory_order_acquire))
          std::this_thread::yield();
        for (uint32_t call = 0; call < 100; ++call) {
          if (driver_->debug_stop_publishable_for_testing(kRdna3GpuId))
            unexpectedly_publishable.store(true, std::memory_order_relaxed);
        }
      });
    }
    while (ready.load(std::memory_order_acquire) != kThreadCount)
      std::this_thread::yield();
    start.store(true, std::memory_order_release);
  }
  EXPECT_FALSE(unexpectedly_publishable.load(std::memory_order_relaxed));
}

struct PreGfx12TrapParam {
  const char *name;
  const char *config_path;
  uint32_t gpu_id;
  uint32_t profiling_move;
  uint32_t exception_move;
  uint32_t sendmsg_interrupt;
  uint32_t trap;
};

void PrintTo(const PreGfx12TrapParam &param, std::ostream *stream) { *stream << param.name; }

class KfdIoctlPreGfx12TrapTest : public KfdIoctlTest,
                                 public ::testing::WithParamInterface<PreGfx12TrapParam> {
protected:
  void SetUp() override { SetUpWithConfig(GetParam().config_path); }
};

TEST(KfdIoctlHelpersTest, ClassifiesEveryPreGfx12TrapInterruptEncodingFamily) {
  struct EncodingCase {
    rj_code_arch_t arch;
    uint32_t profiling_move;
    uint32_t exception_move;
  };
  constexpr EncodingCase kCases[] = {
      {ROCJITSU_CODE_ARCH_CDNA1, 0xBEFC0073u, 0xBEFC006Fu},
      {ROCJITSU_CODE_ARCH_CDNA2, 0xBEFC0073u, 0xBEFC006Fu},
      {ROCJITSU_CODE_ARCH_CDNA3, 0xBEFC0073u, 0xBEFC006Fu},
      {ROCJITSU_CODE_ARCH_CDNA4, 0xBEFC0073u, 0xBEFC006Fu},
      {ROCJITSU_CODE_ARCH_RDNA1, 0xBEFC0373u, 0xBEFC036Fu},
      {ROCJITSU_CODE_ARCH_RDNA2, 0xBEFC0373u, 0xBEFC036Fu},
      {ROCJITSU_CODE_ARCH_RDNA3, 0xBEFD0073u, 0xBEFD006Fu},
      {ROCJITSU_CODE_ARCH_RDNA3_5, 0xBEFD0073u, 0xBEFD006Fu},
  };
  constexpr uint32_t kSNop0 = 0xBF800000u;

  for (const auto &test_case : kCases) {
    EXPECT_TRUE(rocjitsu::kmd::detail::uses_pre_gfx12_trap_interrupt_sites(test_case.arch));
    EXPECT_EQ(rocjitsu::kmd::detail::classify_pre_gfx12_trap_interrupt_site(
                  test_case.arch, test_case.profiling_move, kSNop0),
              rocjitsu::kmd::detail::TrapInterruptSite::Profiling);
    EXPECT_EQ(rocjitsu::kmd::detail::classify_pre_gfx12_trap_interrupt_site(
                  test_case.arch, test_case.exception_move, kSNop0),
              rocjitsu::kmd::detail::TrapInterruptSite::QueueException);
    EXPECT_EQ(rocjitsu::kmd::detail::classify_pre_gfx12_trap_interrupt_site(
                  test_case.arch, test_case.profiling_move, 0),
              rocjitsu::kmd::detail::TrapInterruptSite::Unknown);
  }

  EXPECT_FALSE(
      rocjitsu::kmd::detail::uses_pre_gfx12_trap_interrupt_sites(ROCJITSU_CODE_ARCH_CDNA5));
  EXPECT_FALSE(
      rocjitsu::kmd::detail::uses_pre_gfx12_trap_interrupt_sites(ROCJITSU_CODE_ARCH_RDNA4));
  EXPECT_EQ(rocjitsu::kmd::detail::trap_interrupt_abi(ROCJITSU_CODE_ARCH_CDNA5),
            rocjitsu::kmd::detail::TrapInterruptAbi::Gfx12);
  EXPECT_EQ(rocjitsu::kmd::detail::trap_interrupt_abi(ROCJITSU_CODE_ARCH_RDNA4),
            rocjitsu::kmd::detail::TrapInterruptAbi::Gfx12);
  EXPECT_EQ(rocjitsu::kmd::detail::trap_interrupt_abi(ROCJITSU_CODE_ARCH_RV32I),
            rocjitsu::kmd::detail::TrapInterruptAbi::Unsupported);
  EXPECT_EQ(rocjitsu::kmd::detail::trap_interrupt_abi(ROCJITSU_CODE_ARCH_RV64I),
            rocjitsu::kmd::detail::TrapInterruptAbi::Unsupported);
  EXPECT_EQ(rocjitsu::kmd::detail::trap_interrupt_abi(ROCJITSU_CODE_ARCH_INVALID),
            rocjitsu::kmd::detail::TrapInterruptAbi::Unsupported);
}

TEST_F(KfdIoctlTest, CreateQueueAcceptsOlderAndNewerPayloadSizes) {
  alignas(4096) std::array<std::byte, 8192> ring{};
  alignas(64) std::array<uint64_t, 8> ptrs{};
  for (size_t bytes : {size_t{88}, sizeof(kfd_ioctl_create_queue_args) + 8}) {
    SCOPED_TRACE(bytes);
    kfd_ioctl_create_queue_args args{};
    args.gpu_id = kGpuId;
    args.queue_type = KFD_IOC_QUEUE_TYPE_COMPUTE_AQL;
    args.ring_base_address = reinterpret_cast<uint64_t>(ring.data());
    args.ring_size = static_cast<uint32_t>(ring.size());
    args.read_pointer_address = reinterpret_cast<uint64_t>(&ptrs[0]);
    args.write_pointer_address = reinterpret_cast<uint64_t>(&ptrs[1]);
    args.queue_percentage = 100;
    std::array<std::byte, sizeof(args) + 16> buffer;
    buffer.fill(std::byte{0xa5});
    const size_t copied = std::min(bytes, sizeof(args));
    std::memcpy(buffer.data(), &args, copied);
    ASSERT_EQ(
        driver_->ioctl(rocjitsu::ioctl_with_size(AMDKFD_IOC_CREATE_QUEUE, bytes), buffer.data()),
        0);
    std::memcpy(&args, buffer.data(), copied);
    EXPECT_NE(args.queue_id, 0u);
    EXPECT_EQ(args.doorbell_offset & rocjitsu::KFD_MMAP_TYPE_MASK,
              rocjitsu::KFD_MMAP_TYPE_DOORBELL);
    for (size_t index = copied; index < buffer.size(); ++index)
      EXPECT_EQ(buffer[index], std::byte{0xa5}) << index;
    kfd_ioctl_destroy_queue_args destroy{};
    destroy.queue_id = args.queue_id;
    EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_DESTROY_QUEUE, &destroy), 0);
  }
}

// A compute queue created through KFD is replicated onto every XCD so its
// dispatches can be spread across the whole device; the XCD that owns the queue
// still reads the ring alone. An SDMA queue is per-engine and is not replicated.
TEST_F(KfdIoctlTest, CreateQueueReplicatesComputeQueueAcrossXcds) {
  const uint32_t num_xcds = soc_->num_xcds();
  ASSERT_GT(num_xcds, 1u);

  auto total_registered = [&]() {
    size_t total = 0;
    for (uint32_t xi = 0; xi < num_xcds; ++xi)
      total += soc_->xcd(xi)->command_processor()->registered_queue_count_for_test();
    return total;
  };
  ASSERT_EQ(total_registered(), 0u);

  alignas(4096) std::array<std::byte, 8192> ring{};
  alignas(64) std::array<uint64_t, 8> ptrs{};

  kfd_ioctl_create_queue_args args{};
  args.gpu_id = kGpuId;
  args.queue_type = KFD_IOC_QUEUE_TYPE_COMPUTE_AQL;
  args.ring_base_address = reinterpret_cast<uint64_t>(ring.data());
  args.ring_size = static_cast<uint32_t>(ring.size());
  args.read_pointer_address = reinterpret_cast<uint64_t>(&ptrs[0]);
  args.write_pointer_address = reinterpret_cast<uint64_t>(&ptrs[1]);
  args.queue_percentage = 100;
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &args), 0);

  EXPECT_EQ(total_registered(), num_xcds)
      << "compute queue should be registered on every XCD's command processor";
  for (uint32_t xi = 0; xi < num_xcds; ++xi)
    EXPECT_EQ(soc_->xcd(xi)->command_processor()->registered_queue_count_for_test(), 1u)
        << "xcd" << xi;

  kfd_ioctl_destroy_queue_args destroy{};
  destroy.queue_id = args.queue_id;
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DESTROY_QUEUE, &destroy), 0);
  EXPECT_EQ(total_registered(), 0u) << "destroying the queue should drop every replica";
}

TEST_F(KfdIoctlTest, CuMaskValidatesBitCountAndQueueIdentity) {
  alignas(4096) std::array<std::byte, 8192> ring{};
  alignas(64) std::array<uint64_t, 8> ptrs{};
  kfd_ioctl_create_queue_args queue{};
  queue.gpu_id = kGpuId;
  queue.queue_type = KFD_IOC_QUEUE_TYPE_COMPUTE_AQL;
  queue.ring_base_address = reinterpret_cast<uint64_t>(ring.data());
  queue.ring_size = ring.size();
  queue.read_pointer_address = reinterpret_cast<uint64_t>(&ptrs[0]);
  queue.write_pointer_address = reinterpret_cast<uint64_t>(&ptrs[1]);
  queue.queue_percentage = 100;
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &queue), 0);
  std::array<uint32_t, 32> mask{};
  mask[0] = 1;
  kfd_ioctl_set_cu_mask_args args{};
  args.queue_id = queue.queue_id;
  args.cu_mask_ptr = reinterpret_cast<uint64_t>(mask.data());
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), -EINVAL);
  args.num_cu_mask = 31;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), -EINVAL);
  args.num_cu_mask = 32;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), 0);
  args.num_cu_mask = 1056;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), 0);
  args.cu_mask_ptr = 0;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), -EFAULT);
  args.cu_mask_ptr = 1;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), -EFAULT);
  args.cu_mask_ptr = reinterpret_cast<uint64_t>(mask.data());
  args.queue_id = queue.queue_id + 1;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), -EFAULT);
  kfd_ioctl_destroy_queue_args destroy{};
  destroy.queue_id = queue.queue_id;
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DESTROY_QUEUE, &destroy), 0);
}

class KfdSdmaCuMaskTest : public KfdIoctlTest,
                          public ::testing::WithParamInterface<std::tuple<bool, uint32_t>> {
protected:
  bool rdna() const { return std::get<0>(GetParam()); }

  void SetUp() override {
    SetUpWithConfig(rdna() ? std::string(CONFIG_DIR) + "/gfx1201_r9700.json" : CONFIG_PATH);
    ASSERT_FALSE(HasFatalFailure());
    kfd_ioctl_create_queue_args queue{};
    queue.gpu_id = rdna() ? 8716u : kGpuId;
    queue.queue_type = std::get<1>(GetParam());
    queue.ring_base_address = reinterpret_cast<uint64_t>(ring_.data());
    queue.ring_size = sizeof(ring_);
    queue.read_pointer_address = reinterpret_cast<uint64_t>(&pointers_[0]);
    queue.write_pointer_address = reinterpret_cast<uint64_t>(&pointers_[1]);
    queue.queue_percentage = 100;
    ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &queue), 0);
    mask_args_.queue_id = queue.queue_id;
    mask_args_.num_cu_mask = 32;
    mask_args_.cu_mask_ptr = reinterpret_cast<uint64_t>(&mask_);
    doorbell_ = driver_->mmap(nullptr, 4096, PROT_READ | PROT_WRITE, MAP_SHARED,
                              static_cast<off_t>(queue.doorbell_offset));
    ASSERT_NE(doorbell_, MAP_FAILED);
  }

  alignas(4096) std::array<uint32_t, 1024> ring_{};
  alignas(64) std::array<uint64_t, 8> pointers_{};
  uint32_t mask_ = 0;
  kfd_ioctl_set_cu_mask_args mask_args_{};
  void *doorbell_ = nullptr;
};

TEST_P(KfdSdmaCuMaskTest, AcceptsValidMasksAndKeepsSdmaRunningWithEmptyMask) {
  for (uint32_t mask : {UINT32_MAX, 3u, 0u}) {
    mask_ = mask;
    EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &mask_args_), 0) << "mask=" << mask;
  }

  // The last mask disables every compute CU, but SDMA must still execute.
  // A 32-bit fence writes a sentinel and advances the ring's read pointer.
  alignas(4096) std::array<uint32_t, 1024> destination{};
  const uint64_t address = reinterpret_cast<uint64_t>(destination.data());
  auto process = driver_->find_process(driver_->local_process_id());
  ASSERT_NE(process, nullptr);
  process->map_pages(address, destination.data(), sizeof(destination));
  constexpr uint32_t kSentinel = 0x12345678;
  ring_[0] = 5; // SDMA_OP_FENCE, 32-bit form.
  ring_[1] = static_cast<uint32_t>(address);
  ring_[2] = static_cast<uint32_t>(address >> 32);
  ring_[3] = kSentinel;
  constexpr uint64_t kPacketBytes = 4 * sizeof(uint32_t);
  std::atomic_ref<uint64_t>(pointers_[1]).store(kPacketBytes, std::memory_order_release);
  std::atomic_ref<uint64_t>(*static_cast<uint64_t *>(doorbell_))
      .store(kPacketBytes, std::memory_order_release);
  ASSERT_TRUE(soc_->sdma_queue_scheduler().synchronize_host_queue_for_test(
      driver_->local_process_id(), mask_args_.queue_id));
  EXPECT_EQ(std::atomic_ref<uint64_t>(pointers_[0]).load(std::memory_order_acquire), kPacketBytes);
  EXPECT_EQ(std::atomic_ref<uint32_t>(destination[0]).load(std::memory_order_acquire), kSentinel);
  process->unmap_pages(address, sizeof(destination));
}

TEST_P(KfdSdmaCuMaskTest, ValidatesMaskArguments) {
  mask_args_.num_cu_mask = 0;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &mask_args_), -EINVAL);
  mask_args_.num_cu_mask = 31;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &mask_args_), -EINVAL);
  mask_args_.num_cu_mask = 32;
  mask_args_.cu_mask_ptr = 0;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &mask_args_), -EFAULT);
  mask_args_.cu_mask_ptr = 1;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &mask_args_), -EFAULT);
  mask_args_.cu_mask_ptr = reinterpret_cast<uint64_t>(&mask_);
  for (uint32_t half : {1u, 2u}) {
    mask_ = half;
    EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &mask_args_), rdna() ? -EINVAL : 0);
  }
  ++mask_args_.queue_id;
  EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &mask_args_), -EFAULT);
}

INSTANTIATE_TEST_SUITE_P(KfdMasks, KfdSdmaCuMaskTest,
                         ::testing::Combine(::testing::Values(false, true),
                                            ::testing::Values(KFD_IOC_QUEUE_TYPE_SDMA,
                                                              KFD_IOC_QUEUE_TYPE_SDMA_XGMI,
                                                              KFD_IOC_QUEUE_TYPE_SDMA_BY_ENG_ID)),
                         [](const ::testing::TestParamInfo<std::tuple<bool, uint32_t>> &info) {
                           const std::string architecture =
                               std::get<0>(info.param) ? "Rdna" : "Cdna";
                           switch (std::get<1>(info.param)) {
                           case KFD_IOC_QUEUE_TYPE_SDMA:
                             return architecture + "Sdma";
                           case KFD_IOC_QUEUE_TYPE_SDMA_XGMI:
                             return architecture + "SdmaXgmi";
                           case KFD_IOC_QUEUE_TYPE_SDMA_BY_ENG_ID:
                             return architecture + "SdmaByEngineId";
                           default:
                             ADD_FAILURE() << "Unexpected SDMA queue type";
                             return architecture + "Unknown";
                           }
                         });

struct CuMaskPlacementCase {
  const char *config;
  int bit; // -1 enables all 256 advertised CUs on CDNA4.
  uint32_t xcd;
  uint32_t se;
  uint32_t cu;
};

void PrintTo(const CuMaskPlacementCase &test, std::ostream *out) {
  *out << test.config << "_";
  if (test.bit < 0)
    *out << "AllAdvertised";
  else
    *out << "Bit" << test.bit;
}

class KfdCuMaskPlacementTest : public KfdIoctlTest,
                               public ::testing::WithParamInterface<CuMaskPlacementCase> {
protected:
  void SetUp() override { SetUpWithConfig(std::string(CONFIG_DIR) + "/" + GetParam().config); }
};

TEST_P(KfdCuMaskPlacementTest, CuMaskSelectsOnlyTheRequestedPhysicalUnits) {
  using namespace rocjitsu::amdhsa;
  const CuMaskPlacementCase &test = GetParam();
  const bool rdna = soc_->arch() == ROCJITSU_CODE_ARCH_RDNA4;
  const uint32_t wave_size = rdna ? 32u : 64u;
  const uint32_t workgroups = test.bit < 0 ? 256u : 8u;
  constexpr uint64_t kKernelAddress = 0x10000;
  alignas(4096) std::array<uint8_t, 4096> code{};
  kernel_descriptor_t kd{};
  kd.kernel_code_entry_byte_offset = sizeof(kd);
  kd.group_segment_fixed_size = 128 * 1024;
  RJ_AMDHSA_BITS_SET(kd.kernel_code_properties, KERNEL_CODE_PROPERTY_ENABLE_WAVEFRONT_SIZE32, rdna);
  RJ_AMDHSA_BITS_SET(kd.compute_pgm_rsrc1, COMPUTE_PGM_RSRC1_WGP_MODE, rdna);
  std::memcpy(code.data(), &kd, sizeof(kd));
  const uint32_t endpgm = rocjitsu::build_s_endpgm(soc_->arch());
  std::memcpy(code.data() + sizeof(kd), &endpgm, sizeof(endpgm));
  auto *process = driver_->find_process(driver_->local_process_id()).get();
  ASSERT_NE(process, nullptr);
  process->map_pages(kKernelAddress, code.data(), code.size());

  alignas(4096) std::array<hsa_kernel_dispatch_packet_t, 64> ring{};
  alignas(64) std::array<uint64_t, 8> pointers{};
  kfd_ioctl_create_queue_args queue{};
  queue.gpu_id = rdna ? 8716u : kGpuId;
  queue.queue_type = KFD_IOC_QUEUE_TYPE_COMPUTE_AQL;
  queue.ring_base_address = reinterpret_cast<uint64_t>(ring.data());
  queue.ring_size = sizeof(ring);
  queue.read_pointer_address = reinterpret_cast<uint64_t>(&pointers[0]);
  queue.write_pointer_address = reinterpret_cast<uint64_t>(&pointers[1]);
  queue.queue_percentage = 100;
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_CREATE_QUEUE, &queue), 0);
  void *doorbell = driver_->mmap(nullptr, 4096, PROT_READ | PROT_WRITE, MAP_SHARED,
                                 static_cast<off_t>(queue.doorbell_offset));
  ASSERT_NE(doorbell, MAP_FAILED);

  // RDNA masks enable adjacent CU pairs across SEs and SHs.
  // CDNA4 bits 0/1 select different XCDs; an all-ones mask must exclude the
  // ninth CU in each SE, beyond the device's advertised 256 active CUs.
  std::array<uint32_t, 8> mask{};
  if (test.bit < 0)
    mask.fill(UINT32_MAX);
  else
    mask[test.bit / 32] = (rdna ? 3u : 1u) << (test.bit % 32);
  kfd_ioctl_set_cu_mask_args args{};
  args.queue_id = queue.queue_id;
  args.num_cu_mask = mask.size() * 32;
  args.cu_mask_ptr = reinterpret_cast<uint64_t>(mask.data());
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), 0);

  if (rdna) {
    // Reject either half of a pair, including bits beyond the active CUs.
    // The dispatch below must still use the last successful mask.
    for (uint32_t bit : {0u, static_cast<uint32_t>(test.bit), 254u}) {
      for (uint32_t half : {1u, 2u}) {
        SCOPED_TRACE(bit);
        SCOPED_TRACE(half);
        mask.fill(0);
        mask[bit / 32] = half << (bit % 32);
        EXPECT_EQ(driver_->ioctl(AMDKFD_IOC_SET_CU_MASK, &args), -EINVAL);
      }
    }
  }

  auto &packet = ring[0];
  packet.setup = 1;
  packet.workgroup_size_x = wave_size;
  packet.workgroup_size_y = packet.workgroup_size_z = 1;
  packet.grid_size_x = workgroups * wave_size;
  packet.grid_size_y = packet.grid_size_z = 1;
  packet.kernel_object = kKernelAddress;
  std::atomic_ref<uint16_t>(packet.header)
      .store(HSA_PACKET_TYPE_KERNEL_DISPATCH, std::memory_order_release);
  std::atomic_ref<uint64_t>(pointers[1]).store(1, std::memory_order_release);
  std::atomic_ref<uint64_t>(*static_cast<uint64_t *>(doorbell)).store(0, std::memory_order_release);

  // Exercise the real host-polled KFD path. A direct event injection can run
  // before the monitor has changed last_doorbell from its UINT64_MAX sentinel,
  // in which case the CP must (correctly) treat the queue as unpublished. Give
  // the monitor wall-clock opportunities to observe the release-store while
  // continuing to drain the simulated work it schedules.
  for (unsigned i = 0;
       i < 2000 && std::atomic_ref<uint64_t>(pointers[0]).load(std::memory_order_acquire) != 1;
       ++i) {
    (void)engine_->step();
    std::this_thread::sleep_for(std::chrono::microseconds(50));
  }
  EXPECT_EQ(std::atomic_ref<uint64_t>(pointers[0]).load(std::memory_order_acquire), 1u);
  for (unsigned i = 0; i < 200; ++i)
    (void)engine_->step();
  uint64_t dispatched = 0;
  for (uint32_t xcd = 0; xcd < soc_->num_xcds(); ++xcd) {
    auto *chiplet = soc_->xcd(xcd);
    dispatched += chiplet->command_processor()->dispatched_workgroups();
    for (uint32_t se = 0; se < chiplet->num_shader_engines(); ++se) {
      auto *shader = chiplet->shader_engine(se);
      for (uint32_t cu = 0; cu < shader->num_compute_units(); ++cu) {
        const bool selected = test.bit < 0 ? cu < 8
                                           : xcd == test.xcd && se == test.se &&
                                                 (cu == test.cu || (rdna && cu == test.cu + 1));
        EXPECT_EQ(shader->compute_unit(cu)->cycle_count() > 0, selected)
            << "XCD=" << xcd << " SE=" << se << " CU=" << cu;
      }
    }
  }
  EXPECT_EQ(dispatched, workgroups);
  kfd_ioctl_destroy_queue_args destroy{};
  destroy.queue_id = queue.queue_id;
  ASSERT_EQ(driver_->ioctl(AMDKFD_IOC_DESTROY_QUEUE, &destroy), 0);
  // The driver retains doorbell mappings until process teardown in TearDown().
  process->unmap_pages(kKernelAddress, code.size());
}

